(56, 'setting', 'Setting was created', 'App\\Models\\Setting', 7, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":7,\"key\":\"services_page\",\"value\":\"{\\\"page_name\\\":\\\"Our Services\\\",\\\"hero_title_html\\\":\\\"Comprehensive <span class=\\\\\\\"text-indigo-400\\\\\\\">Healthcare<\\\\\\/span> Solutions\\\",\\\"hero_description\\\":\\\"From primary consultations to advanced diagnostics, we provide all your outpatient needs under one professional roof.\\\",\\\"hero_image\\\":\\\"assets\\\\\\/front\\\\\\/images\\\\\\/services\\\\\\/services.jpg\\\",\\\"section_badge\\\":\\\"Patient-Centered Care\\\",\\\"section_title\\\":\\\"Integrated Services for Everyday Health Needs\\\",\\\"section_description\\\":\\\"We combine consultation, diagnostics, preventive screening, and digital follow-up to ensure every patient receives complete and coordinated care.\\\",\\\"block_1_badge\\\":\\\"Expert Guidance\\\",\\\"block_1_title\\\":\\\"Personalized Consultations\\\",\\\"block_1_description\\\":\\\"Our doctors spend meaningful time understanding each patient. Consult in person or virtually and receive practical care plans tailored to your condition and goals.\\\",\\\"block_1_button_text\\\":\\\"Explore Specialities\\\",\\\"block_1_button_url\\\":\\\"\\\\\\/video-consultation\\\",\\\"block_1_image\\\":\\\"assets\\\\\\/front\\\\\\/images\\\\\\/services\\\\\\/con4.jpg\\\",\\\"block_2_badge\\\":\\\"Advanced Diagnostics\\\",\\\"block_2_title\\\":\\\"Reliable Testing with Modern Technology\\\",\\\"block_2_description\\\":\\\"Our laboratories and diagnostics workflow are designed for consistency, speed, and clinical accuracy, helping doctors and patients make timely decisions with confidence.\\\",\\\"block_2_button_text\\\":\\\"View Lab Tests\\\",\\\"block_2_button_url\\\":\\\"\\\\\\/lab-test\\\",\\\"block_2_image\\\":\\\"assets\\\\\\/front\\\\\\/images\\\\\\/services\\\\\\/con3.jpeg\\\",\\\"catalog_title\\\":\\\"Available Services\\\",\\\"catalog_description\\\":\\\"Browse our active services below. Each test or procedure includes essential details to help you choose the right care path.\\\",\\\"empty_state_text\\\":\\\"No services are available right now. Please check again shortly.\\\"}\",\"created_at\":\"2026-03-03T13:10:28.000000Z\",\"updated_at\":\"2026-03-03T13:10:28.000000Z\"}}', 'created', NULL, '2026-03-03 07:10:29', '2026-03-03 07:10:29'),
(57, 'setting', 'Setting was created', 'App\\Models\\Setting', 8, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":8,\"key\":\"blog_page\",\"value\":\"{\\\"page_name\\\":\\\"Blog\\\",\\\"hero_title_html\\\":\\\"Health <span class=\\\\\\\"text-indigo-400\\\\\\\">Insights<\\\\\\/span> & Stories\\\",\\\"hero_description\\\":\\\"Read expert perspectives, wellness tips, and updates from Imperial Health.\\\",\\\"hero_image\\\":\\\"assets\\\\\\/front\\\\\\/images\\\\\\/services\\\\\\/services.jpg\\\",\\\"founder_badge\\\":\\\"Our Story\\\",\\\"founder_title\\\":\\\"Meet Our Founder & Chair of the Board\\\",\\\"founder_description\\\":\\\"Six years ago, my mother was hospitalized at one of Bangladesh\'s top hospitals for a basic operation. We expected that the routine procedure would go smoothly, yet she suffered dramatic complications. That experience taught us that empathy, transparency, and quality must come first in healthcare.\\\",\\\"founder_button_text\\\":\\\"See Details\\\",\\\"founder_button_url\\\":\\\"#\\\",\\\"founder_image\\\":\\\"assets\\\\\\/front\\\\\\/images\\\\\\/management\\\\\\/1.jpg\\\",\\\"blog_list_title\\\":\\\"Our Latest Blog\\\",\\\"blogs_per_page\\\":\\\"8\\\"}\",\"created_at\":\"2026-03-03T13:33:53.000000Z\",\"updated_at\":\"2026-03-03T13:33:53.000000Z\"}}', 'created', NULL, '2026-03-03 07:33:53', '2026-03-03 07:33:53'),
