(4, 'Imperial Private Health Care (BD) Ltd. (Banglamotor Branch)', 'Imperial Private Health Care (BD) Ltd. (Banglamotor Branch)', 'imperial-private-health-care-bd-ltd-banglamotor-branch', 'Imperial Private Health Care (BD) Ltd. at Banglamotor provides trusted medical services. Located on the 3rd floor of Rupayan Trade Center, 114 Kazi Nazrul Islam Avenue. Open for emergency cases. Call 09604109666 or 01332556541 for immediate assistance. Visit our convenient Dhaka location today.', NULL, NULL, 'Rupayan Trade center(3rd floor) 114 Kazi Nazrul Islam Avenue Bangla Motor, Dhaka 1000', 'Call: \r\n+88 09604109666\r\n+88 01332556541', 'uploads/branches/banglamotor-branch.jpg', 'https://maps.app.goo.gl/FGdQpq8aofXKgCyB9', 'Call: +88 09604109666 +88 01332556541', NULL, NULL, NULL, NULL, '2026-04-28 13:03:50', '2026-04-30 00:39:25'),
(5, 'Imperial Private Health Care (BD) Ltd. (Hatirpool Branch)', 'Imperial Private Health Care (BD) Ltd. (Hatirpool Branch)', 'imperial-private-health-care-bd-ltd-hatirpool-branch', 'Imperial Private Health Care (BD) Ltd. at Hatirpool offers dedicated medical care. Located on Level 1 of Navana Paragon Tower, 162 C.R. Dutta Road. Available for emergency cases. Call +88 09604109666 or +88 01335100543 for urgent support. Visit our Hatirpool branch today.', NULL, NULL, '162, Navana Paragon Tower (Level 1), C.R. Dutta Road, Hatirpool, Dhaka-1205', 'Call: \r\n+88 09604109666\r\n+88 01335100543', 'uploads/branches/branch_feature_1786809297_0kR4h.jpeg', 'https://maps.app.goo.gl/mi5wPciWFQ5nnYjj9', 'Call: +88 09604109666 +88 01335100543', NULL, NULL, NULL, NULL, '2026-04-28 13:03:50', '2026-08-15 09:55:10');
