INSERT INTO `health_packages` (`id`, `health_package_category_id`, `page_name`, `name`, `slug`, `subtitle`, `badge_text`, `price`, `old_price`, `discount_text`, `image`, `description`, `duration`, `turnaround`, `fasting`, `inclusions`, `preparation_steps`, `faq_1_question`, `faq_1_answer`, `faq_2_question`, `faq_2_answer`, `recommended`, `immediate_availability`, `show_on_frontend`, `status`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 1, 'Package Details', 'Imperial Women’s Wellness Check – Under 40', 'her-health-under-40-1772465158-1', 'Deep dive into our specialized health package designed to give you a complete picture of your wellness.', 'Comprehensive Screening', 13800.00, 18000.00, 'Save 23%', 'uploads/health_packages/imperial-womens-wellness-under-40.png', 'A preventive screening package for women under 40 focusing on metabolic, hormonal, and cardiovascular markers.', '4-6 Hours', '24-48 Hours', '10-12 Hours', 'Complete Blood Count (CBC)\nLipid Profile\nLiver Function Test (LFT)\nKidney Function Test (KFT)\nBlood Glucose (Fasting)\nThyroid Profile (T3, T4, TSH)', 'Complete fasting for 10-12 hours is required. Water is allowed.\nAvoid smoking and alcohol for at least 24 hours before tests.\nBring previous medical reports and prescriptions on visit day.', 'Do I need to book in advance?', 'Yes, advance booking is recommended to ensure faster processing and dedicated slots.', 'When will I receive my reports?', 'Most reports are available within 24-48 hours depending on test complexity.', 1, 1, 1, 1, 1, '2026-03-02 09:25:58', '2026-08-17 06:35:09'),
(2, 1, 'Package Details', 'Imperial Women’s Wellness Check – 40 to 65', 'her-health-40-65-1772465158-2', 'Deep dive into our specialized health package designed to give you a complete picture of your wellness.', 'Comprehensive Screening', 22200.00, 28000.00, 'Save 21%', 'uploads/health_packages/imperial-womens-wellness-40-to-65.png', 'An expanded diagnostic panel for women aged 40 to 65 including cardiac and endocrine risk profiling.', '4-6 Hours', '24-48 Hours', '10-12 Hours', 'Complete Blood Count (CBC)\nLipid Profile\nLiver Function Test (LFT)\nKidney Function Test (KFT)\nBlood Glucose (Fasting)\nThyroid Profile (T3, T4, TSH)', 'Complete fasting for 10-12 hours is required. Water is allowed.\nAvoid smoking and alcohol for at least 24 hours before tests.\nBring previous medical reports and prescriptions on visit day.', 'Do I need to book in advance?', 'Yes, advance booking is recommended to ensure faster processing and dedicated slots.', 'When will I receive my reports?', 'Most reports are available within 24-48 hours depending on test complexity.', 0, 1, 1, 1, 2, '2026-03-02 09:25:58', '2026-08-17 06:35:09'),
(3, 2, 'Package Details', 'Imperial Men’s Wellness Check – Under 40', 'his-health-under-40-1772465158-3', 'Deep dive into our specialized health package designed to give you a complete picture of your wellness.', 'Comprehensive Screening', 13800.00, 17500.00, 'Save 21%', 'uploads/health_packages/imperial-mens-wellness-under-40.png', 'A foundational wellness package for men under 40 with complete blood, sugar, lipid and organ health checks.', '4-6 Hours', '24-48 Hours', '10-12 Hours', 'Complete Blood Count (CBC)\nLipid Profile\nLiver Function Test (LFT)\nKidney Function Test (KFT)\nBlood Glucose (Fasting)\nThyroid Profile (T3, T4, TSH)', 'Complete fasting for 10-12 hours is required. Water is allowed.\nAvoid smoking and alcohol for at least 24 hours before tests.\nBring previous medical reports and prescriptions on visit day.', 'Do I need to book in advance?', 'Yes, advance booking is recommended to ensure faster processing and dedicated slots.', 'When will I receive my reports?', 'Most reports are available within 24-48 hours depending on test complexity.', 0, 1, 1, 1, 3, '2026-03-02 09:25:58', '2026-08-17 06:35:09'),
(4, 2, 'Package Details', 'Imperial Men’s Wellness Check – 40 to 65', 'his-health-40-65-1772465158-4', 'Deep dive into our specialized health package designed to give you a complete picture of your wellness.', 'Comprehensive Screening', 22200.00, 28500.00, 'Save 22%', 'uploads/health_packages/imperial-mens-wellness-40-to-65.png', 'A comprehensive package for men aged 40 to 65 with focused cardiac, liver, kidney, thyroid and prostate indicators.', '4-6 Hours', '24-48 Hours', '10-12 Hours', 'Complete Blood Count (CBC)\nLipid Profile\nLiver Function Test (LFT)\nKidney Function Test (KFT)\nBlood Glucose (Fasting)\nThyroid Profile (T3, T4, TSH)', 'Complete fasting for 10-12 hours is required. Water is allowed.\nAvoid smoking and alcohol for at least 24 hours before tests.\nBring previous medical reports and prescriptions on visit day.', 'Do I need to book in advance?', 'Yes, advance booking is recommended to ensure faster processing and dedicated slots.', 'When will I receive my reports?', 'Most reports are available within 24-48 hours depending on test complexity.', 0, 1, 1, 1, 4, '2026-03-02 09:25:58', '2026-08-17 06:35:09'),
