(3, 'emails', '{\"host\":\"localhost\",\"port\":\"3306\",\"username\":\"heatmap\",\"password\":\"557799\",\"encryption\":\"tts\",\"from_address\":\"admin@imperial.com\",\"from_name\":\"Imperial\",\"header_color\":\"#c43e00\",\"footer_color\":\"#363636\",\"patient_code\":{\"subject\":\"Patient Code\",\"body\":\"<p>Welcome , {patient_name}<\\/p><p>Your patient code is : {patient_code}&nbsp;<\\/p>\",\"active\":false},\"reset_password\":{\"subject\":\"Reset Password\",\"body\":null,\"active\":false},\"tests_notification\":{\"subject\":\"tests reports completed\",\"body\":\"welcome , {patient_name} <br>  your tests are ready now .. you can check tests by using your patient code : {patient_code}\",\"active\":false}}', NULL, '2026-03-03 05:34:28'),
