(7, 'services_page', '{\"page_name\":\"Our Services\",\"hero_title_html\":\"Comprehensive <span class=\\\"text-indigo-400\\\">Healthcare<\\/span> Solutions\",\"hero_description\":\"From primary consultations to advanced diagnostics, we provide all your outpatient needs under one professional roof.\",\"hero_image\":\"uploads\\/branches\\/hatirpool-branch.jpg\",\"section_badge\":\"Patient-Centered Care\",\"section_title\":\"Integrated Services for Everyday Health Needs\",\"section_description\":\"We combine consultation, diagnostics, preventive screening, and digital follow-up to ensure every patient receives complete and coordinated care.\",\"block_1_badge\":\"Expert Guidance\",\"block_1_title\":\"Personalized Consultations\",\"block_1_description\":\"Our doctors spend meaningful time understanding each patient. Consult in person or virtually and receive practical care plans tailored to your condition and goals.\",\"block_1_button_text\":\"Explore Specialities\",\"block_1_button_url\":\"\\/video-consultation\",\"block_1_image\":\"assets\\/front\\/images\\/services\\/consultation-corridor.jpg\",\"block_2_badge\":\"Advanced Diagnostics\",\"block_2_title\":\"Reliable Testing with Modern Technology\",\"block_2_description\":\"Our laboratories and diagnostics workflow are designed for consistency, speed, and clinical accuracy, helping doctors and patients make timely decisions with confidence.\",\"block_2_button_text\":\"View Lab Tests\",\"block_2_button_url\":\"\\/lab-test\",\"block_2_image\":\"assets\\/front\\/images\\/services\\/con3.jpeg\",\"catalog_title\":\"Available Services\",\"catalog_description\":\"Browse our active services below. Each test or procedure includes essential details to help you choose the right care path.\",\"empty_state_text\":\"No services are available right now. Please check again shortly.\"}', '2026-03-03 07:10:28', '2026-08-17 05:34:19'),
(8, 'blog_page', '{\"page_name\":\"Blog\",\"hero_title_html\":\"Health <span class=\\\"text-indigo-400\\\">Insights<\\/span> & Stories\",\"hero_description\":\"Read expert perspectives, wellness tips, and updates from Imperial Health.\",\"hero_image\":\"uploads\\/branches\\/hatirpool-branch.jpg\",\"founder_badge\":\"Our Story\",\"founder_title\":\"Meet Our Founder & Chair of the Board\",\"founder_description\":\"\",\"founder_button_text\":\"See Details\",\"founder_button_url\":\"#\",\"founder_image\":\"assets\\/front\\/images\\/management\\/1.jpg\",\"blog_list_title\":\"Our Latest Blog\",\"blogs_per_page\":\"8\"}', '2026-03-03 07:33:53', '2026-08-17 05:34:19'),
(9, 'home_page', '{\"hero\":{\"slides\":[{\"badge\":\"Lab at Doorstep\",\"title_html\":\"Hassle-Free <br>Diagnostic <span class=\\\"text-indigo-400\\\">Tests<\\/span>\",\"description\":\"Avoid the traffic and wait. Our experts come to you for sample collection in the comfort of your home.\",\"button_text\":\"Book Home Test\",\"button_url\":\"\\/lab-test\",\"image\":\"uploads\\/home\\/hero\\/home-sample-collection.png\"},{\"badge\":\"Patient-Centered Care\",\"title_html\":\"Care That <span class=\\\"text-indigo-400\\\">Puts You First<\\/span>\",\"description\":\"From the moment you arrive, our team is here to help - with full wheelchair accessibility and attentive support for every patient.\",\"button_text\":\"Explore Health Checks\",\"button_url\":\"\\/health-check\",\"image\":\"uploads\\/home\\/hero\\/affordable-healthchecks.png\"},{\"badge\":\"In-House Pharmacy\",\"title_html\":\"Your Medicines, <span class=\\\"text-indigo-400\\\">Under One Roof<\\/span>\",\"description\":\"Fill your prescriptions right after your consultation at our in-house Imperial Pharmacy - no extra trips needed.\",\"button_text\":\"Contact Us\",\"button_url\":\"\\/contact\",\"image\":\"uploads\\/home\\/hero\\/imperial-pharmacy.png\"},{\"badge\":\"Welcome to Imperial\",\"title_html\":\"Every <span class=\\\"text-indigo-400\\\">Patient Matters<\\/span>\",\"description\":\"Step into a reception built around you - clear guidance, friendly staff, and care from the moment you walk in.\",\"button_text\":\"Visit Our Branches\",\"button_url\":\"\\/branches\",\"image\":\"uploads\\/home\\/hero\\/reception.png\"},{\"badge\":\"Family Care\",\"title_html\":\"Caring for Your Health, <span class=\\\"text-indigo-400\\\">Every Step of the Way<\\/span>\",\"description\":\"From routine checkups to specialist consultations, our team looks after every member of your family.\",\"button_text\":\"Meet Our Doctors\",\"button_url\":\"\\/doctor\",\"image\":\"uploads\\/home\\/hero\\/family-consultation.png\"}]},\"about\":{\"badge\":\"About Imperial\",\"title_html\":\"Redefining the <span class=\\\"text-indigo-600\\\">Patient Experience<\\/span>\",\"description\":\"At Imperial Health, your care starts with being heard. Our doctors, diagnostics, and support teams work together under one roof, so you spend less time coordinating appointments and more time focused on getting better.\"},\"stats\":{\"specialities_count\":\"16\",\"specialities_label\":\"Specialities\",\"doctors_count\":\"27\",\"doctors_label\":\"Expert Doctors\",\"patients_count\":\"\",\"patients_label\":\"Patients Served\"},\"doctor_carousel\":{\"badge\":\"Our Specialists\",\"title_html\":\"Meet Our <span class=\\\"text-indigo-600\\\">Expert Doctors<\\/span>\",\"description\":\"Browse a fresh selection of Imperial Health specialists on every visit and connect with the right doctor for your care needs.\",\"button_text\":\"View All Doctors\",\"button_url\":\"\\/doctor\"},\"our_approach\":{\"badge\":\"Our Approach\",\"title_html\":\"Doctors Who <span class=\\\"text-indigo-600\\\">Take the Time<\\/span>\",\"description_1\":\"Our specialists dedicate time to truly understand your health history. We believe in respect, empathy, and personalized advice based on international clinical protocols.\",\"description_2\":\"With years of local and international experience, our team provides healthcare you can trust blindly.\",\"button_text\":\"Find a Specialist\",\"button_url\":\"\\/doctor\",\"image\":\"assets\\/front\\/images\\/index\\/why-imperial.jpg\"},\"lab_excellence\":{\"badge\":\"Lab Excellence\",\"title_html\":\"Diagnostics You Can <span class=\\\"text-emerald-600\\\">Trust<\\/span>\",\"description\":\"Accuracy is our top priority. Our lab team follows careful quality-control procedures at every step, from sample collection to reporting, so you can trust every result.\",\"feature_1\":\"Quality-Checked\",\"feature_2\":\"Trained Technicians\",\"button_text\":\"Explore Our Services\",\"button_url\":\"\\/lab-test\",\"image\":\"assets\\/front\\/images\\/index\\/lab-directory.jpg\"},\"experience_imperial\":{\"badge\":\"Experience Imperial\",\"title_html\":\"Take a Virtual Tour of Our Facility\",\"description\":\"Step inside our world-class medical center. From our luxury waiting areas to state-of-the-art diagnostic labs, experience the Imperial difference.\",\"button_text\":\"Start The Tour\",\"button_url\":\"#\",\"image\":\"assets\\/front\\/images\\/index\\/tour.jpg\"},\"continuous_care\":{\"title_html\":\"Continuous Care for <br><span class=\\\"text-indigo-600\\\">Your Family<\\/span>\",\"description\":\"Our membership plans are designed to provide proactive health management with unlimited family doctor consultations, health checks, and exclusive discounts.\",\"button_text\":\"Explore Membership\",\"button_url\":\"\\/membership\"},\"expert_advice\":{\"title_html\":\"Expert Advice from <br><span class=\\\"text-indigo-400\\\">Comfort of Home<\\/span>\",\"description\":\"Can\'t visit the hub? Connect with our world-class specialists via high-definition, secure video consultations. Reliable care, anywhere you are.\",\"button_text\":\"Book Video Consult\",\"button_url\":\"\\/video-consultation\"},\"ceo_message\":{\"enabled\":\"1\",\"badge\":\"CEO\'s Message\",\"title_html\":\"A Message from Our <span class=\\\"text-indigo-600\\\">CEO<\\/span>\",\"message\":\"At Imperial Health, we believe that every patient deserves world-class healthcare delivered with compassion and excellence. Our mission is to redefine the healthcare experience in Bangladesh by combining cutting-edge medical technology with a patient-first approach. We are committed to providing accessible, affordable, and high-quality care to every individual who walks through our doors.\",\"name\":\"Md Mahbubor Rahman\",\"designation\":\"Chief Executive Officer\",\"image\":\"uploads\\/home\\/sections\\/ceo_message_1774894150.jpg\"},\"sections_order\":[{\"key\":\"hero\",\"enabled\":true},{\"key\":\"branches\",\"enabled\":true},{\"key\":\"about_stats\",\"enabled\":true},{\"key\":\"doctor_carousel\",\"enabled\":false},{\"key\":\"our_approach\",\"enabled\":true},{\"key\":\"lab_excellence\",\"enabled\":true},{\"key\":\"experience_imperial\",\"enabled\":true},{\"key\":\"membership_video_cta\",\"enabled\":true}]}', '2026-03-30 12:01:44', '2026-08-15 06:35:40'),
(10, 'gallery_page', '{\"page_name\":\"Gallery\",\"hero_title_html\":\"Our <span class=\\\"text-indigo-400\\\">Gallery<\\/span>\",\"hero_description\":\"Explore moments from our hospital, events, and healthcare services.\",\"hero_image\":\"uploads\\/branches\\/hatirpool-branch.jpg\"}', '2026-04-30 06:15:21', '2026-08-17 05:34:19'),
